#include<bits/stdc++.h>
using namespace std;
const int maxn =1e5 + 5;
#define ll long long 
// cnt[i][0] 代表这n个整数中，第i位分别出现了多少次0 
// cnt[i][1] 代表这n个整数中，第i位分别出现了多少次1 
ll cnt[40][2];
int main (){
    int n;
    cin >> n;
    for (int i = 1 ; i <= n; i++){
		ll x;
		cin >> x;
        // 统计x
		for (int j = 0 ; j < 34 ; j++){
			int v = (x >> j) & 1;
			cnt[j][v]++;
		}
    }
    // 按二进制的每一位计算贡献
    int ans = 0;
    for (int i = 0 ; i < 34 ; i++){
        // 看最小出现次数。
    	ans += min(cnt[i][0] , cnt[i][1]);
    }
    cout << ans << endl;
    return 0;
}
